            { title: "FastAPI + LangGraph", text: "Agent IA Python 3.12 avec un StateGraph stateful : interprétation NL, sourcing SerpAPI/MCP, enrichissement Apollo.io, embeddings sentence-transformers et évaluation Llama 3.3 70B via Groq." },
            { title: "React 19 + Vite 8", text: "SPA complète avec Context API, Axios, Lucide React, TailwindCSS 4, Vitest + 624 tests, Oxlint et Nginx pour la production." }
